// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC20/IERC20.sol";

contract DePayMProtocol {

    

    // ──────── MULTISIG GOVERNANCE ────────
    address[] public signers;
    uint256 public constant requiredApprovals = 2;

    function isSigner(address _address) public view returns (bool) {
        for (uint i = 0; i < signers.length; i++) {
            if (signers[i] == _address) {
                return true;
            }
        }
        return false;
    }

    struct Action {
        bytes32 id;
        address proposer;
        bytes data;
        uint8 approvals;
        bool executed;
        mapping(address => bool) approvedBy;
    }

    mapping(bytes32 => Action) private actions;

    modifier onlySigner() {
    bool valid = false;
    for (uint i = 0; i < signers.length; i++) {
        if (signers[i] == msg.sender) {
            valid = true;
            break;
        }
    }
    require(valid, "Not authorized signer");
    _;
}


    modifier onlySelf() {
        require(msg.sender == address(this), "Only executable via proposal");
        _;
    }

    constructor(
    address _feeCollector,
    address[] memory _signers
) payable {
    require(_feeCollector != address(0), "Invalid fee collector");
    require(_signers.length == 3, "Need exactly 3 signers");

    feeCollector = _feeCollector;
    signers = _signers;
}


    // ──────── PROTOCOL ACTIONS ────────

    struct FeeTier {
        uint256 minAmount;
        uint256 fixedFee;
    }
    FeeTier[] public feeTiers;
    uint256 public constant MAX_DAILY_AMOUNT = 100_000 * 1e6;
    uint256 public constant WITHDRAW_FEE_BPS = 110; // 1.1%
    uint256 public constant DEPOSIT_FEE_BPS = 240; // 2.4%

    address public feeCollector;
    mapping(address => bool) public supportedStablecoins;
    mapping(address => uint256) public lastTxTime;
    mapping(address => uint256) public dailyVolume;

    event PaymentExecuted(
        address indexed user,
        address indexed receiver,
        address indexed token,
        uint256 receiverAmount,
        uint256 tierFee
    );
    event WithdrawalExecuted(
        address indexed user,
        address indexed receiver,
        address indexed token,
        uint256 receiverAmount,
        uint256 tierFee,
        uint256 withdrawFee
    );
    event DepositExecuted(
        address indexed user,
        address indexed receiver,
        address indexed token,
        uint256 amount,
        uint256 netAmount,
        uint256 tierFee,
        uint256 depositFee
    );
    event FeeDetails(
        uint256 receiverAmount,
        uint256 tierFee,
        uint256 totalAmount
    );
    event ActionProposed(
        bytes32 indexed actionId,
        address indexed proposer
        );
    event ActionApproved(
        bytes32 indexed actionId,
        address indexed approver
    );
    event ActionExecuted(
        bytes32 indexed actionId,
        address indexed executor
        );

    // ─── PAY ───────────────────────────────────────────────────────────────────
    function pay(
        address user,
        address token,
        address receiver,
        uint256 receiverAmount,
        uint256 totalAmount
    ) external {
        uint256 tierFee = getTierFee(receiverAmount);
        require(
            totalAmount == receiverAmount + tierFee,
            "Invalid total amount"
        );
        emit FeeDetails(receiverAmount, tierFee, totalAmount);

        require(supportedStablecoins[token], "Unsupported token");
        _updateDailyLimit(user, totalAmount);
        require(
            IERC20(token).allowance(user, address(this)) >= totalAmount,
            "Insufficient allowance"
        );

        require(
            user != address(0) && token != address(0) && receiver != address(0),
            "Invalid address"
        );

        _transfer(token, user, receiver, receiverAmount);
        _transfer(token, user, feeCollector, tierFee);

        emit PaymentExecuted(user, receiver, token, receiverAmount, tierFee);
    }

    // ─── WITHDRAW ─────────────────────────────────────────────────────────────
    function withdraw(
        address user,
        address token,
        address receiver,
        uint256 receiverAmount,
        uint256 totalAmount
    ) external {
        uint256 withdrawFee = (receiverAmount * WITHDRAW_FEE_BPS) / 10_000;
        uint256 tierFee = getTierFee(receiverAmount);
        require(
            totalAmount == receiverAmount + tierFee + withdrawFee,
            "Invalid total amount"
        );
        emit FeeDetails(receiverAmount, tierFee + withdrawFee, totalAmount);

        require(supportedStablecoins[token], "Unsupported token");
        _updateDailyLimit(user, totalAmount);
        require(
            IERC20(token).allowance(user, address(this)) >= totalAmount,
            "Insufficient allowance"
        );

        require(
            user != address(0) && token != address(0) && receiver != address(0),
            "Invalid address"
        );

        _transfer(token, user, receiver, receiverAmount + withdrawFee);
        _transfer(token, user, feeCollector, tierFee);

        emit WithdrawalExecuted(
            user,
            receiver,
            token,
            receiverAmount,
            tierFee,
            withdrawFee
        );
    }

    function _initTiers() private {
        feeTiers.push(FeeTier(0, 0.1 * 1e6));
        feeTiers.push(FeeTier(5 * 1e6, 0.18 * 1e6));
        feeTiers.push(FeeTier(15 * 1e6, 0.265 * 1e6));
        feeTiers.push(FeeTier(50 * 1e6, 0.371 * 1e6));
        feeTiers.push(FeeTier(100 * 1e6, 0.71 * 1e6));
        feeTiers.push(FeeTier(500 * 1e6, 1.35 * 1e6));
        feeTiers.push(FeeTier(1000 * 1e6, 2.85 * 1e6));
        feeTiers.push(FeeTier(2500 * 1e6, 5.57 * 1e6));
        feeTiers.push(FeeTier(5000 * 1e6, 10.23 * 1e6));
        feeTiers.push(FeeTier(10000 * 1e6, 19.62 * 1e6));
        feeTiers.push(FeeTier(30000 * 1e6, 35.47 * 1e6));
        feeTiers.push(FeeTier(70000 * 1e6, 60.95 * 1e6));
               
    }

    // ─── DEPOSIT ──────────────────────────────────────────────────────────────
    function deposit(
        address token,
        address receiver,
        uint256 amount
    ) external {
        require(supportedStablecoins[token], "Unsupported token");
        require(receiver != address(0), "Invalid receiver");

        uint256 depositFee = (amount * DEPOSIT_FEE_BPS) / 10_000;
        uint256 tierFee = getTierFee(amount);
        uint256 totalFee = depositFee + tierFee;

        uint256 netAmount = amount - totalFee;

        // Update daily limit for msg.sender
        _updateDailyLimit(msg.sender, amount);

        // Transfer full amount from sender to contract
        require(
            IERC20(token).allowance(msg.sender, address(this)) >= amount,
            "Insufficient allowance"
        );
        require(
            IERC20(token).balanceOf(msg.sender) >= amount,
            "Insufficient balance"
        );

        // Transfer tokens
        IERC20(token).transferFrom(msg.sender, receiver, netAmount); // send to receiver
        IERC20(token).transferFrom(msg.sender, address(this), depositFee); // pull depositFee to contract
        IERC20(token).transfer(msg.sender, depositFee); // reward sender
        IERC20(token).transferFrom(msg.sender, feeCollector, tierFee); // send tier fee to feeCollector

        emit DepositExecuted(
            msg.sender,
            receiver,
            token,
            amount,
            tierFee,
            depositFee,
            netAmount
        );
    }

    function _transfer(
        address token,
        address from,
        address to,
        uint256 amt
    ) private {
        require(IERC20(token).transferFrom(from, to, amt), "Transfer failed");
    }

    function getTierFee(uint256 amount) public view returns (uint256) {
        for (uint256 i = feeTiers.length; i > 0; i--) {
            if (amount >= feeTiers[i - 1].minAmount) {
                return feeTiers[i - 1].fixedFee;
            }
        }
        return 0;
    }

    function _updateDailyLimit(address who, uint256 amount) internal {
        if (block.timestamp > lastTxTime[who] + 1 days) {
            dailyVolume[who] = 0;
        }
        require(
            dailyVolume[who] + amount <= MAX_DAILY_AMOUNT,
            "Daily cap exceeded"
        );
        dailyVolume[who] += amount;
        lastTxTime[who] = block.timestamp;
    }

    

    // ──────── ADMIN ACTIONS ────────

    function updateFeeCollector(address newCollector) external onlySelf {
        feeCollector = newCollector;
    }

    function updateStablecoin(address token, bool ok) external onlySelf {
        supportedStablecoins[token] = ok;
    }

    function updateSigner(uint index, address newSigner) external onlySelf {
    require(index < signers.length, "Invalid index");
    require(newSigner != address(0), "Zero address");
    signers[index] = newSigner;
}


    function withdrawNative(address payable to, uint256 amt) external onlySelf {
        to.transfer(amt);
    }

    function recoverTokens(address token, uint256 amount) external onlySelf {
        IERC20(token).transfer(feeCollector, amount);
    }

    receive() external payable {}

    // ──────── MULTISIG PROPOSAL SYSTEM ────────

    bytes32[] public pendingActionIds;

    function proposeAction(bytes memory data) external onlySigner returns (bytes32) {
        bytes32 actionId = keccak256(abi.encode(data, block.timestamp, msg.sender));
        Action storage action = actions[actionId];
        require(action.approvals == 0, "Already proposed");

        action.id = actionId;
        action.proposer = msg.sender;
        action.data = data;
        action.approvals = 1;
        action.executed = false;
        action.approvedBy[msg.sender] = true;

        // Add to pending actions list
        pendingActionIds.push(actionId);

        emit ActionProposed(actionId, msg.sender);
        return actionId;
    }

    function approveAction(bytes32 actionId) external onlySigner {
        Action storage action = actions[actionId];
        require(!action.executed, "Already executed");
        require(!action.approvedBy[msg.sender], "Already approved");

        action.approvals += 1;
        action.approvedBy[msg.sender] = true;

        emit ActionApproved(actionId, msg.sender);
    }

    function executeAction(bytes32 actionId) external onlySigner {
        Action storage action = actions[actionId];
        require(!action.executed, "Already executed");
        require(action.approvals >= requiredApprovals, "Not enough approvals");

        (bool success, ) = address(this).call(action.data);
        require(success, "Execution failed");

        action.executed = true;
        
        // Remove from pending actions
        for (uint i = 0; i < pendingActionIds.length; i++) {
            if (pendingActionIds[i] == actionId) {
                // Swap with last element and pop
                pendingActionIds[i] = pendingActionIds[pendingActionIds.length - 1];
                pendingActionIds.pop();
                break;
            }
        }

        emit ActionExecuted(actionId, msg.sender);
    }

    function getPendingActions() external view returns (bytes32[] memory) {
    // First count pending actions
    uint count = 0;
    for (uint i = 0; i < pendingActionIds.length; i++) {
        if (!actions[pendingActionIds[i]].executed) {
            count++;
        }
    }

    // Then populate the return array
    bytes32[] memory pending = new bytes32[](count);
    uint index = 0;
    for (uint i = 0; i < pendingActionIds.length; i++) {
        if (!actions[pendingActionIds[i]].executed) {
            pending[index] = pendingActionIds[i];
            index++;
        }
    }
    return pending;
}
    function getActionDetails(bytes32 actionId) external view returns (
        address proposer,
        bytes memory data,
        uint8 approvals,
        bool executed
    ) {
        Action storage action = actions[actionId];
        return (action.proposer, action.data, action.approvals, action.executed);
    }

    function isActionApprovedBy(bytes32 actionId, address signer) external view returns (bool) {
        return actions[actionId].approvedBy[signer];
    }
}

